    def __init__(self):
        self.prices = {
            "basic": (1.00, False),
            "pro": (0.90, True)
        }

    def price(self, plan, amount):
        if plan in self.prices:
            discount_factor, _ = self.prices[plan]
            return round(amount * discount_factor, 2)
        raise KeyError(plan)

    def rename_plan(self, old, new):
        if old in self.prices:
            discount_factor, is_renamed = self.prices.pop(old)
            self.prices[new] = (discount_factor, True)
            if is_renamed:
                del self.prices[old]
        else:
            raise KeyError(old)
