class Permissions:
    def __init__(self):
        self.roles = defaultdict(set)
        self.inheritance = defaultdict(set)

    def define_role(self, name, actions, inherits=None):
        if inherits:
            for parent in inherits.split():
                self.inheritance[name].add(parent)
                self.inheritance[parent].add(name)
        self.roles[name] |= set(actions)

    def allowed(self, role, action):
        return self._resolve_inheritance(role, action)

    def _resolve_inheritance(self, role, action):
        if action in self.roles[role]:
            return True
        for parent in self.inheritance[role]:
            if self._resolve_inheritance(parent, action):
                return True
        return False
