from collections import defaultdict

class Permissions:
    def __init__(self):
        self.roles = defaultdict(set)
        self.inheritance = defaultdict(set)

    def define_role(self, name, actions, inherits=None):
        if inherits:
            for parent in inherits.split():
                self.inheritance[name].update(self.roles[parent])
        self.roles[name].update(actions)

    def allowed(self, role, action):
        return action in self._get_permissions(role)

    def _get_permissions(self, role):
        permissions = set(self.roles[role])
        stack = [role]
        while stack:
            current = stack.pop()
            for parent in self.inheritance[current]:
                if parent not in permissions:
                    permissions.add(parent)
                    stack.append(parent)
        return permissions
